import test from 'node:test';
import assert from 'node:assert/strict';
import { clamp } from '../src/clamp-upper.mjs';
test('visible behavior',()=>{ assert.equal(clamp(3, 0, 5), 3); assert.equal(clamp(8, 0, 5), 5); });

import test from 'node:test';
import assert from 'node:assert/strict';
import { median } from '../src/median-even.mjs';
test('visible behavior',()=>{ assert.equal(median([3,1,2]), 2); assert.equal(median([1,4,2,3]), 2.5); });

import test from 'node:test';
import assert from 'node:assert/strict';
import { unique } from '../src/stable-unique.mjs';
